package pl.maciek.squashscoreboard;

import android.app.Activity;import android.content.Intent;import android.graphics.Color;import android.os.Bundle;import android.view.*;import android.widget.*;import org.json.JSONObject;import java.util.Locale;
public class MatchDetailActivity extends Activity {
 public static final String EXTRA_RECORD="record";
 @Override public void onCreate(Bundle state){super.onCreate(state);try{showRecord(MatchRecord.fromJson(new JSONObject(getIntent().getStringExtra(EXTRA_RECORD))));}catch(Exception e){finish();}}
 private void showRecord(MatchRecord r){boolean dark=AppPreferences.dark(this);int background=dark?Color.rgb(13,16,22):Color.rgb(245,247,250),foreground=dark?Color.WHITE:Color.rgb(24,30,40),muted=dark?Color.rgb(174,185,201):Color.rgb(80,92,108);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(7),dp(18),dp(7));root.setBackgroundColor(background);TextView back=text("<  HISTORIA",16,muted);back.setGravity(Gravity.CENTER_VERTICAL);back.setOnClickListener(v->finish());TextView names=text(r.playerOneName+"  vs  "+r.playerTwoName,19,foreground);names.setGravity(Gravity.CENTER);TextView result=text(r.playerOneSets+" : "+r.playerTwoSets,24,muted);result.setGravity(Gravity.CENTER);TextView duration=text(r.durationMs>0?"CZAS MECZU: "+formatDuration(r.durationMs):"CZAS MECZU: brak danych",14,muted);duration.setGravity(Gravity.CENTER);TextView setTimes=text(setTimes(r),13,muted);setTimes.setGravity(Gravity.CENTER);TextView caption=text("PRZEBIEG PUNKTOW  -  DOTKNIJ WYKRESU, ABY POWIEKSZYC",12,muted);caption.setGravity(Gravity.CENTER);root.addView(back,new LinearLayout.LayoutParams(-1,dp(27)));root.addView(names,new LinearLayout.LayoutParams(-1,dp(27)));root.addView(result,new LinearLayout.LayoutParams(-1,dp(26)));root.addView(duration,new LinearLayout.LayoutParams(-1,dp(21)));root.addView(setTimes,new LinearLayout.LayoutParams(-1,dp(21)));root.addView(caption,new LinearLayout.LayoutParams(-1,dp(17)));ChartPager charts=new ChartPager(this);charts.setPageCount(4);charts.setHorizontalScrollBarEnabled(false);LinearLayout pages=new LinearLayout(this);pages.setOrientation(LinearLayout.HORIZONTAL);charts.addView(pages);root.addView(charts,new LinearLayout.LayoutParams(-1,0,1));TextView dots=text("●  ○  ○  ○",18,muted);dots.setGravity(Gravity.CENTER);root.addView(dots,new LinearLayout.LayoutParams(-1,dp(24)));charts.post(()->{int w=charts.getWidth();View score=new ScoreChartView(this,r),progress=new SetProgressChartView(this,r),sets=new SetsChartView(this,r),stats=new MatchStatsView(this,r);score.setOnClickListener(v->openFullscreen(0));progress.setOnClickListener(v->openFullscreen(1));sets.setOnClickListener(v->openFullscreen(2));pages.addView(score,new LinearLayout.LayoutParams(w,-1));pages.addView(progress,new LinearLayout.LayoutParams(w,-1));pages.addView(sets,new LinearLayout.LayoutParams(w,-1));pages.addView(stats,new LinearLayout.LayoutParams(w,-1));charts.setOnScrollChangeListener((v,x,y,ox,oy)->{int p=Math.round(x/(float)Math.max(1,w));dots.setText(p==0?"●  ○  ○  ○":p==1?"○  ●  ○  ○":p==2?"○  ○  ●  ○":"○  ○  ○  ●");caption.setText(p==3?"STATYSTYKI MECZU":"PRZEBIEG PUNKTOW  -  DOTKNIJ WYKRESU, ABY POWIEKSZYC");});});LinearLayout legend=new LinearLayout(this);legend.setGravity(Gravity.CENTER);TextView p1=text("● "+r.playerOneName,15,r.playerOneColor),p2=text("● "+r.playerTwoName,15,r.playerTwoColor);legend.addView(p1,new LinearLayout.LayoutParams(0,-1,1));legend.addView(p2,new LinearLayout.LayoutParams(0,-1,1));root.addView(legend,new LinearLayout.LayoutParams(-1,dp(25)));Button resume=new Button(this);resume.setText(r.finished?"KONTYNUUJ MECZ":"WZNOW MECZ");resume.setTextColor(Color.WHITE);resume.setTextSize(14);resume.setOnClickListener(v->{startActivity(new Intent(this,MainActivity.class).putExtra(EXTRA_RECORD,getIntent().getStringExtra(EXTRA_RECORD)).putExtra("continue",r.finished));finish();});root.addView(resume,new LinearLayout.LayoutParams(-1,dp(42)));setContentView(root);}
 private void openFullscreen(int chart){startActivity(new Intent(this,ChartFullscreenActivity.class).putExtra(ChartFullscreenActivity.EXTRA_RECORD,getIntent().getStringExtra(EXTRA_RECORD)).putExtra(ChartFullscreenActivity.EXTRA_CHART,chart));}
 private String setTimes(MatchRecord r){if(r.setDurationsMs.isEmpty())return "CZASY SETOW: brak danych";StringBuilder s=new StringBuilder("CZASY SETOW: ");for(int i=0;i<r.setDurationsMs.size();i++){if(i>0)s.append("  -  ");s.append(i+1).append(". ").append(formatDuration(r.setDurationsMs.get(i)));}return s.toString();}private String formatDuration(long ms){long s=Math.max(0,ms)/1000;return String.format(Locale.US,"%02d:%02d",s/60,s%60);}private TextView text(String v,int size,int c){TextView t=new TextView(this);t.setText(v);t.setTextSize(size);t.setTextColor(c);return t;}private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
}
